package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

public class TarUtils_parseOctal_TriageGen1Test {

    @Test
    public void testParseOctal_ValidSimple() {
        byte[] buffer = "000123".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, 6);
        assertEquals(83L, result); // 123 octal = 1*64 + 2*8 + 3 = 83
    }

    @Test
    public void testParseOctal_WithLeadingSpaces() {
        byte[] buffer = "   007".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, 6);
        assertEquals(7L, result);
    }

    @Test
    public void testParseOctal_WithTrailingNulsAndSpaces() {
        // Test trailing spaces and null bytes (0)
        byte[] buffer = "010  \0\0".getBytes();
        // length is 8: '0','1','0',' ',' ','\0','\0'
        // Note: the loop for trailer checks buffer[end-1]
        long result = TarUtils.parseOctal(buffer, 0, 7);
        assertEquals(8L, result);
    }

    @Test
    public void testParseOctal_WithMiddleNull() {
        byte[] buffer = "010\007".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, 5);
        assertEquals(8L, result); // Should stop at the first null
    }

    @Test
    public void testParseOctal_FirstByteIsZero() {
        byte[] buffer = new byte[]{0, 1, 2, 3};
        long result = TarUtils.parseOctal(buffer, 0, 4);
        assertEquals(0L, result);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_LengthTooShort() {
        byte[] buffer = "0".getBytes();
        TarUtils.parseOctal(buffer, 0, 1);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidOctalDigit() {
        byte[] buffer = "018".getBytes(); // 8 is invalid
        TarUtils.parseOctal(buffer, 0, 3);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidNonDigit() {
        byte[] buffer = "01A".getBytes(); // A is invalid
        TarUtils.parseOctal(buffer, 0, 3);
    }

    @Test
    public void testParseOctal_OffsetUsage() {
        byte[] buffer = "ABC012XYZ".getBytes();
        // Offset 3, length 3 -> "012"
        long result = TarUtils.parseOctal(buffer, 3, 3);
        assertEquals(10L, result); // 1*8 + 2 = 10
    }

    @Test
    public void testParseOctal_LargeValue() {
        // Max long value in octal representation
        byte[] buffer = "777777777777".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, 12);
        // 777777777777 octal is a large number
        long expected = 0;
        for (int i = 0; i < 12; i++) {
            expected = (expected << 3) + 7;
        }
        assertEquals(expected, result);
    }

    @Test
    public void testParseOctal_AllSpacesTrailing() {
        byte[] buffer = "012  ".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, 5);
        assertEquals(10L, result);
    }

    @Test
    public void testParseOctal_AllSpacesLeadingAndTrailing() {
        byte[] buffer = "  012  ".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, 7);
        assertEquals(10L, result);
    }

    @Test
    public void testParseOctal_OnlySpacesAndNulls() {
        // If length >= 2 and first byte is 0 (null), it returns 0
        byte[] buffer = {0, 0, 0};
        long result = TarUtils.parseOctal(buffer, 0, 3);
        assertEquals(0L, result);
    }

    @Test
    public void testParseOctal_BoundaryConditionEnd() {
        // Test where start becomes equal to end after trimming
        byte[] buffer = "  \0 ".getBytes();
        // buffer[0] is ' ', buffer[1] is ' ', buffer[2] is 0, buffer[3] is ' '
        // Length 4.
        // First byte is ' ', not 0.
        // Skip leading spaces: start becomes 2.
        // Trailer logic: buffer[3] is ' ', end becomes 3. buffer[2] is 0, end becomes 2.
        // start (2) is not < end (2). Loop doesn't run.
        // However, the method requires length >= 2.
        // If buffer[start] == 0 is checked before space skipping:
        // In the code: if (buffer[start] == 0) return 0.
        // Here buffer[0] is ' ', so it proceeds.
        // If the buffer was {0, 32, 32}, it returns 0 immediately.
        byte[] buffer2 = {0, 32, 32}; 
        assertEquals(0L, TarUtils.parseOctal(buffer2, 0, 3));
    }
}
